import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";

export type TranscriptMetadata = {
  /** Whether the transcript was automatically generated using AI. */
  autogenerated: boolean;
  /** The ID of the video. */
  clipId: number;
  /** The ID of the container. */
  containerId: string;
  /** Whether the transcript has been marked as deleted. */
  deleted: boolean;
  /** Whether the transcript is enabled. */
  enabled: boolean;
  /** The ID of the transcript. */
  id: string;
  /**
   * The kind of transcript. The value of this field can be `captions` for caption transcripts or
   * `subtitles` for subtitle transcripts.
   */
  kind: string;
  /** The language in which the transcript appears. */
  language: string;
  /** The total number of speakers in the transcript. */
  speakerCount: number;
  /** The ID of the text track. */
  texttrackId: number;
  /** The UUID of the transcript status. */
  transcriptStatusUuid: string;
  /** The total number of words in the transcript. */
  wordCount: number;
};

export const transcriptMetadataSchema: Schema<TranscriptMetadata> = s.object<TranscriptMetadata>({
  autogenerated: s.boolean(),
  clipId: s.float64(),
  containerId: s.string(),
  deleted: s.boolean(),
  enabled: s.boolean(),
  id: s.string(),
  kind: s.string(),
  language: s.string(),
  speakerCount: s.float64(),
  texttrackId: s.float64(),
  transcriptStatusUuid: s.string(),
  wordCount: s.float64(),
  _keysMap: {
    clipId: "clip_id",
    containerId: "container_id",
    speakerCount: "speaker_count",
    texttrackId: "texttrack_id",
    transcriptStatusUuid: "transcript_status_uuid",
    wordCount: "word_count",
  },
});
